package com.arjunren.loan.service;
import com.arjunren.loan.domain.*; import com.arjunren.loan.dto.Dtos.*; import com.arjunren.loan.entity.*; import com.arjunren.loan.exception.DomainException; import com.arjunren.loan.repository.*; import java.math.*; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class LoanService{private final LoanApplicationRepository loans;private final RepaymentRepository repayments;public LoanService(LoanApplicationRepository l,RepaymentRepository r){loans=l;repayments=r;}@Transactional public LoanResponse apply(ApplyRequest r,AppUser actor){requireCustomer(actor);return LoanResponse.of(loans.save(new LoanApplication(actor,money(r.principal()),r.termMonths(),r.purpose().trim())));}@Transactional(readOnly=true)public LoanResponse get(Long id,AppUser actor){return LoanResponse.of(visible(loans.findById(id).orElseThrow(()->notFound()),actor));}@Transactional(readOnly=true)public PageResponse<LoanResponse>list(AppUser actor,LoanStatus status,int page,int size){Pageable p=PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt"));Page<LoanApplication>x;if(actor.getRole()==Role.CUSTOMER)x=status==null?loans.findByCustomerId(actor.getId(),p):loans.findByCustomerIdAndStatus(actor.getId(),status,p);else x=status==null?loans.findAll(p):loans.findByStatus(status,p);return new PageResponse<>(x.map(LoanResponse::of).getContent(),page,size,x.getTotalElements(),x.getTotalPages());}@Transactional public LoanResponse approve(Long id,BigDecimal rate,AppUser officer){requireStaff(officer);var l=lock(id);requireStatus(l,LoanStatus.PENDING);BigDecimal annual=rate.setScale(4,RoundingMode.UNNECESSARY);BigDecimal interest=l.getPrincipal().multiply(annual).divide(new BigDecimal("100"),8,RoundingMode.HALF_UP).multiply(new BigDecimal(l.getTermMonths())).divide(new BigDecimal("12"),2,RoundingMode.HALF_UP);l.approve(annual,l.getPrincipal().add(interest).setScale(2),officer);return LoanResponse.of(l);}@Transactional public LoanResponse reject(Long id,String reason,AppUser officer){requireStaff(officer);var l=lock(id);requireStatus(l,LoanStatus.PENDING);l.reject(reason.trim(),officer);return LoanResponse.of(l);}@Transactional public LoanResponse disburse(Long id,AppUser officer){requireStaff(officer);var l=lock(id);requireStatus(l,LoanStatus.APPROVED);l.disburse();return LoanResponse.of(l);}@Transactional public RepaymentResponse repay(Long id,BigDecimal amount,AppUser actor){var l=lock(id);visible(l,actor);requireStatus(l,LoanStatus.DISBURSED);BigDecimal v=money(amount);if(v.compareTo(l.getOutstandingBalance())>0)throw new DomainException(HttpStatus.CONFLICT,"Payment exceeds outstanding balance");l.repay(v);return RepaymentResponse.of(repayments.save(new Repayment(l,v,UUID.randomUUID().toString(),actor)));}@Transactional(readOnly=true)public PageResponse<RepaymentResponse>payments(Long id,AppUser actor,int page,int size){visible(loans.findById(id).orElseThrow(()->notFound()),actor);var p=repayments.findByLoanId(id,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"paidAt")));return new PageResponse<>(p.map(RepaymentResponse::of).getContent(),page,size,p.getTotalElements(),p.getTotalPages());}public long count(LoanStatus s){return loans.countByStatus(s);}private LoanApplication lock(Long id){return loans.findByIdForUpdate(id).orElseThrow(()->notFound());}private LoanApplication visible(LoanApplication l,AppUser u){if(u.getRole()==Role.CUSTOMER&&!l.getCustomer().getId().equals(u.getId()))throw new DomainException(HttpStatus.FORBIDDEN,"Cannot access another customer's loan");return l;}private void requireCustomer(AppUser u){if(u.getRole()!=Role.CUSTOMER)throw new DomainException(HttpStatus.FORBIDDEN,"Only customers can apply");}private void requireStaff(AppUser u){if(u.getRole()==Role.CUSTOMER)throw new DomainException(HttpStatus.FORBIDDEN,"Loan officer or admin role required");}private void requireStatus(LoanApplication l,LoanStatus s){if(l.getStatus()!=s)throw new DomainException(HttpStatus.CONFLICT,"Loan status must be "+s);}private BigDecimal money(BigDecimal v){return v.setScale(2,RoundingMode.UNNECESSARY);}private DomainException notFound(){return new DomainException(HttpStatus.NOT_FOUND,"Loan not found");}}

